import { useState } from "react";
import { getCommandes, annulerCommande } from "../services/serviceCommandes";
import { Link } from "react-router-dom";

const couleur = "#3B5BDB";
const toDH = (euros) => `${(euros * 10.8).toFixed(2)} DH`;

const STATUTS = {
  en_cours: {
    label: "En cours",
    bg: "#EEF2FF",
    color: couleur,
    image: "https://images.unsplash.com/photo-1566576721346-d4a3b4eaeb55?w=40&q=80",
  },
  livree: {
    label: "Livrée",
    bg: "#E6FCF5",
    color: "#0CA678",
    image: "https://images.unsplash.com/photo-1518458028785-8fbcd101ebb9?w=40&q=80",
  },
  annulee: {
    label: "Annulée",
    bg: "#FFF5F5",
    color: "#E03131",
    image: "https://images.unsplash.com/photo-1580902394724-b08ff42e0a58?w=40&q=80",
  },
};

const ETAPES = [
  { label: "Commande passée", image: "https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?w=60&q=80" },
  { label: "En préparation", image: "https://images.unsplash.com/photo-1553413077-190dd305871c?w=60&q=80" },
  { label: "En livraison", image: "https://images.unsplash.com/photo-1566576721346-d4a3b4eaeb55?w=60&q=80" },
  { label: "Livrée", image: "https://images.unsplash.com/photo-1518458028785-8fbcd101ebb9?w=60&q=80" },
];

function getEtapeActive(statut) {
  if (statut === "livree") return 3;
  if (statut === "annulee") return 0;
  return 2;
}

export default function MesCommandes() {
  const [commandes, setCommandes] = useState(getCommandes());
  const [commandeOuverte, setCommandeOuverte] = useState(null);
  const [confirmation, setConfirmation] = useState(null);

  const handleAnnuler = (id) => {
    annulerCommande(id);
    setCommandes(getCommandes());
    setConfirmation(null);
  };

  if (commandes.length === 0) {
    return (
      <div style={{ textAlign: "center", padding: "80px 20px" }}>
        <img
          src="https://images.unsplash.com/photo-1607082348824-0a96f2a4b9da?w=200&q=80"
          alt=""
          style={{ width: "160px", height: "160px", borderRadius: "50%", objectFit: "cover", opacity: 0.5 }}
        />
        <h2>Aucune commande</h2>
        <p>Vous n'avez pas encore passé de commande.</p>
        <Link to="/catalogue">
          <button>Voir le catalogue →</button>
        </Link>
      </div>
    );
  }

  const commandeDetail = commandes.find((c) => c.id === commandeOuverte);

  return (
    <div>
      {/* MODAL */}
      {confirmation && (
        <div style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.45)", display: "flex", justifyContent: "center", alignItems: "center" }}>
          <div style={{ background: "white", padding: "30px", borderRadius: "12px", textAlign: "center" }}>
            <h3>Annuler la commande ?</h3>
            <button onClick={() => handleAnnuler(confirmation)}>Oui</button>
            <button onClick={() => setConfirmation(null)}>Non</button>
          </div>
        </div>
      )}

      <h1>Mes Commandes</h1>

      <div style={{ display: "grid", gridTemplateColumns: commandeOuverte ? "1fr 400px" : "1fr", gap: "20px" }}>
        {/* LISTE */}
        <div>
          {commandes.map((cmd) => {
            const statut = cmd.statut || "en_cours";
            const s = STATUTS[statut];

            return (
              <div key={cmd.id} style={{ border: "1px solid #ddd", marginBottom: "10px", padding: "10px" }}>
                <p>Commande #{cmd.id}</p>
                <p>{s.label}</p>
                <button onClick={() => setCommandeOuverte(cmd.id)}>Voir détail</button>
              </div>
            );
          })}
        </div>

        {/* DETAIL */}
        {commandeDetail && (
          <div style={{ border: "1px solid #ddd", padding: "20px" }}>
            <h2>Commande #{commandeDetail.id}</h2>

            {/* 🔥 PARTIE ANNULÉE AVEC IMAGE */}
            {commandeDetail.statut === "annulee" ? (
              <div style={{ background: "#FFF5F5", padding: "16px", borderRadius: "12px", textAlign: "center" }}>
                <img
                  src="https://images.unsplash.com/photo-1580902394724-b08ff42e0a58?w=400&q=80"
                  alt="Commande annulée"
                  style={{
                    width: "100%",
                    height: "160px",
                    objectFit: "cover",
                    borderRadius: "10px",
                    marginBottom: "12px",
                  }}
                />

                <p style={{ fontWeight: "bold", color: "#E03131" }}>
                  Commande annulée
                </p>

                <p>Cette commande a été annulée définitivement.</p>
              </div>
            ) : (
              <p>Commande en cours...</p>
            )}

            <button onClick={() => setConfirmation(commandeDetail.id)}>
              Annuler
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
